class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        def _insert(node, key):
            if not node: return TreeNode(key)
            if key < node.key: node.left = _insert(node.left, key)
            elif key > node.key: node.right = _insert(node.right, key)
            return node
        self.root = _insert(self.root, key)

    def contains(self, key):
        curr = self.root
        while curr:
            if curr.key == key: return True
            curr = curr.left if key < curr.key else curr.right
        return False

    def inorder(self):
        def _traverse(node):
            return _traverse(node.left) + [node.key] + _traverse(node.right) if node else []
        return _traverse(self.root)

    def height(self):
        def _h(node):
            return -1 if not node else 1 + max(_h(node.left), _h(node.right))
        return _h(self.root)

    def min(self):
        if not self.root: return None
        curr = self.root
        while curr.left: curr = curr.left
        return curr.key

def build(keys):
    tree = BST()
    for k in keys: tree.insert(k)
    return tree

print(build([50, 30, 70, 20, 40, 80]).inorder())

